"""Model configuration: structural options (enums) and integer costs.

Every structural alternative of the plan's "Model" table is a field here; the
fitter enumerates them and never tunes them continuously. Integer costs are
CPU clocks. Bus facts (3-clock cycle plus waits) are not parameters: wait
counts come from the chain's WTC (field 0 memory, field 7 I/O).
"""

from __future__ import annotations

import copy
import json
from dataclasses import asdict, dataclass, field, fields
from pathlib import Path

